import { Browser } from "../../packages/engine/tests/web/cdp.ts";
import { writeFileSync } from "node:fs";
import { inflateRawSync } from "node:zlib";
import { createHash } from "node:crypto";
import { loadavg } from "node:os";

const records: unknown[] = [];
const open = Browser.prototype.open;
Browser.prototype.open = async function (...args) {
  await Bun.sleep(60_000);
  const loadBefore = loadavg();
  const page = await open.apply(this, args);
  await page.prepareWorkers(async (worker, session) => {
    if (worker.url.endsWith("/game.js")) {
      await page.evalWorker(session, `addEventListener("message", e => { if(e.data.type === "start") globalThis.__measurementStart = e.data; });`);
    }
  });
  const evaluate = page.eval.bind(page);
  page.eval = async function (expression, contextId) {
    const result = await evaluate(expression, contextId);
    if (expression.includes("const each = [], step = [], render = []")) {
      const session = [...page.workers].find(([, w]) => w.url.endsWith("/game.js"))?.[0];
      if (!session) throw new Error("engine Worker not attached");
      const raw = await page.evalWorker<any>(session, `(async () => {
        const start = globalThis.__measurementStart;
        const wasm = await import(start.lanes?.glue ?? start.glue);
        return { stats: JSON.parse(wasm.og_physics_stats(0)), snapshot: JSON.parse(wasm.og_world_snapshot(0)), glue: start.lanes?.glue ?? start.glue };
      })()`);
      if (!raw.snapshot.ok || !raw.stats.ok) throw new Error(JSON.stringify(raw));
      const payload = inflateRawSync(Buffer.from(raw.snapshot.value.split(":")[2], "base64"));
      if (payload.toString("ascii", 0, 4) !== "OGSV") throw new Error("not OGSV");
      const snapshot = payload.subarray(24);
      records.push({ loadBefore, loadAfter: loadavg(), stats: raw.stats.value, glue: raw.glue,
        tick: Number(payload.readBigUInt64LE(8)), snapshotBytes: snapshot.length,
        wholeWorldSnapshotSha256: createHash("sha256").update(snapshot).digest("hex"),
        saveChecksumFnv64: payload.readBigUInt64LE(16).toString(16),
      });
      writeFileSync(process.env.LANES_RECEIPT!, JSON.stringify(records, null, 2) + "\n");
    }
    return result;
  };
  return page;
};
